insert into public.areas (id, slug, name_de, name_vi, description_de, description_vi, icon, color, is_shared, sort) values
  ('00000000-0000-0000-0000-00000000a000', 'fuer-alle', 'Für alle', 'Cho tất cả mọi người',
   'Das Fundament für jede Rolle. Lies diese Seiten in deiner ersten Woche.',
   'Nền tảng cho mọi vai trò. Hãy đọc các trang này trong tuần đầu tiên.', 'users', '#0B7793', true, 0),
  ('00000000-0000-0000-0000-00000000a001', 'sales', 'Sales & Kundenservice', 'Kinh doanh & Chăm sóc khách hàng',
   'Du bist die erste Stimme von NaNu NaNa: Du beantwortest Anfragen, berätst ehrlich und begleitest bis zur Anmeldung.',
   'Bạn là tiếng nói đầu tiên của NaNu NaNa: trả lời câu hỏi, tư vấn trung thực và đồng hành đến khi học viên đăng ký.', 'chat', '#D9542C', false, 1),
  ('00000000-0000-0000-0000-00000000a002', 'student-support', 'Customer Success / Student Support', 'Hỗ trợ học viên',
   'APS, Visum, Studienkolleg – wir begleiten bis zur Ankunft in Deutschland.',
   'APS, visa, dự bị đại học – đồng hành đến khi đặt chân tới Đức.', 'heart', '#13946F', false, 2),
  ('00000000-0000-0000-0000-00000000a003', 'lehrkraft', 'Lehrkraft', 'Giáo viên',
   'Unterricht A1–C1, Prüfungsvorbereitung und Feedback.', 'Giảng dạy A1–C1, luyện thi và nhận xét học viên.', 'cap', '#4C5FD5', false, 3),
  ('00000000-0000-0000-0000-00000000a004', 'lehrmaterialien', 'Lehrmaterialien', 'Tài liệu giảng dạy',
   'Arbeitsblätter, Vokabellisten und Videolektionen.', 'Bài tập, danh sách từ vựng và video bài giảng.', 'book', '#C68A10', false, 4),
  ('00000000-0000-0000-0000-00000000a005', 'redaktion', 'Redaktion: Content & Social Media', 'Biên tập: Nội dung & mạng xã hội',
   'Facebook, TikTok, Erklärvideos und Redaktionsplan.', 'Facebook, TikTok, video giải thích và lịch nội dung.', 'pen', '#C9417F', false, 5),
  ('00000000-0000-0000-0000-00000000a006', 'operations', 'Operations Manager (je Standort)', 'Quản lý vận hành (từng cơ sở)',
   'Räume, Stundenpläne, Kasse und Team vor Ort.', 'Phòng học, lịch học, thu chi và đội ngũ tại chỗ.', 'building', '#2F7DC0', false, 6),
  ('00000000-0000-0000-0000-00000000a007', 'management', 'Management', 'Ban điều hành',
   'Strategie, Finanzen und Partner in Deutschland.', 'Chiến lược, tài chính và đối tác tại Đức.', 'compass', '#6E52C2', false, 7);

-- ---------------------------------------------------------------- Für alle
insert into public.pages (area_id, slug, title_de, title_vi, kind, section, verified_until, body) values
('00000000-0000-0000-0000-00000000a000', 'geschichte-und-werte', 'Unsere Geschichte & Werte', 'Câu chuyện & giá trị của chúng ta', 'decision', 'general', current_date + 120,
 '[{"type":"paragraph","de":"Qualität und Freundlichkeit – darauf bauen wir NaNu NaNa.","vi":"Chất lượng và sự tử tế – nền tảng của NaNu NaNa."},
   {"type":"heading","de":"Was uns wichtig ist","vi":"Điều chúng ta coi trọng"},
   {"type":"list","items":[{"de":"Ehrlich beraten – auch wenn die Antwort „Nein“ ist","vi":"Tư vấn trung thực – kể cả khi câu trả lời là „không“"},{"de":"Radikale Preistransparenz","vi":"Minh bạch học phí tuyệt đối"},{"de":"Begleitung bis zur Ankunft in Deutschland","vi":"Đồng hành đến khi đặt chân tới Đức"}]},
   {"type":"video","url":"","caption_de":"Willkommensvideo der Gründer (YouTube-Link einfügen)","caption_vi":"Video chào mừng từ nhà sáng lập (thêm link YouTube)"}]'),
('00000000-0000-0000-0000-00000000a000', 'kurse-und-leistungen', 'Kurse & Leistungen', 'Khóa học & dịch vụ', 'reference', 'general', current_date + 90,
 '[{"type":"list","items":[{"de":"A1 – 40 Einheiten","vi":"A1 – 40 buổi"},{"de":"A2 – 42 Einheiten","vi":"A2 – 42 buổi"},{"de":"B1 & Prüfungsvorbereitung – 44 Einheiten","vi":"B1 & luyện thi – 44 buổi"},{"de":"B2 – 58 Einheiten","vi":"B2 – 58 buổi"},{"de":"C1 – 58 Einheiten (TestDaF, DSH, Goethe C1)","vi":"C1 – 58 buổi (TestDaF, DSH, Goethe C1)"},{"de":"Kommunikationskurs","vi":"Lớp giao tiếp"}]}]'),
('00000000-0000-0000-0000-00000000a000', 'preise-und-positionierung', 'Preise & Positionierung', 'Học phí & định vị', 'decision', 'general', current_date + 60,
 '[{"type":"callout","tone":"info","de":"Radikale Preistransparenz: keine versteckten Gebühren, gleicher Preis für alle.","vi":"Minh bạch học phí tuyệt đối: không phí ẩn, một mức giá cho tất cả."},
   {"type":"paragraph","de":"[PREISLISTE EINFÜGEN]","vi":"[THÊM BẢNG HỌC PHÍ]"}]'),
('00000000-0000-0000-0000-00000000a000', 'standorte-und-team', 'Standorte & Team', 'Cơ sở & đội ngũ', 'reference', 'general', current_date + 90,
 '[{"type":"list","items":[{"de":"Hồ Chí Minh","vi":"Hồ Chí Minh"},{"de":"Hà Nội","vi":"Hà Nội"},{"de":"Stuttgart","vi":"Stuttgart"}]}]'),
('00000000-0000-0000-0000-00000000a000', 'tools', 'Tools, die wir nutzen', 'Công cụ chúng ta dùng', 'process', 'general', null,
 '[{"type":"paragraph","de":"Slack, Notion, Zalo, Facebook Messenger, Google Workspace und Canva. Facebook Messenger ist unser erster Kontaktkanal, Zalo nutzen wir für alles danach.","vi":"Slack, Notion, Zalo, Facebook Messenger, Google Workspace và Canva. Messenger là kênh liên hệ đầu tiên, Zalo dùng cho các bước sau."}]'),
('00000000-0000-0000-0000-00000000a000', 'allgemeine-regeln', 'Allgemeine Regeln', 'Quy định chung', 'reference', 'general', current_date + 180,
 '[{"type":"paragraph","de":"Arbeitszeiten, Urlaub, Datenschutz und Kommunikation.","vi":"Giờ làm, nghỉ phép, bảo mật dữ liệu và giao tiếp."}]');

-- ---------------------------------------------------------------- Sales
insert into public.pages (id, area_id, slug, title_de, title_vi, kind, section, verified_until, body) values
('00000000-0000-0000-0000-0000000b0001', '00000000-0000-0000-0000-00000000a001', 'erstkontakt-messenger',
 'Erstkontakt über Messenger beantworten', 'Trả lời tin nhắn đầu tiên qua Messenger', 'process', 'handbook', current_date + 80,
 '[{"type":"heading","de":"Ziel","vi":"Mục tiêu"},
   {"type":"paragraph","de":"Jede neue Anfrage auf Facebook Messenger beantworten wir sofort – bevor die Person das Interesse verliert oder eine andere Schule fragt. Persönlich, ehrlich und mit einem klaren nächsten Schritt.","vi":"Mọi tin nhắn mới trên Facebook Messenger được trả lời ngay lập tức – trước khi khách mất hứng thú hoặc hỏi trường khác. Thân thiện, trung thực và có bước tiếp theo rõ ràng."},
   {"type":"callout","tone":"info","de":"Die erste Nachricht entscheidet über den Eindruck. Lieber kurz und herzlich als lang und perfekt.","vi":"Tin nhắn đầu tiên quyết định ấn tượng. Ngắn gọn và ấm áp tốt hơn dài và hoàn hảo."},
   {"type":"video","url":"","caption_de":"So beantwortest du eine Anfrage (Erklärvideo – YouTube-Link einfügen)","caption_vi":"Cách trả lời tin nhắn (video hướng dẫn – thêm link YouTube)"},
   {"type":"heading","de":"Schritt für Schritt","vi":"Từng bước"},
   {"type":"steps","items":[
     {"de":"Anfrage öffnen und Kontext prüfen","vi":"Mở tin nhắn và kiểm tra bối cảnh","body_de":"Schau, über welche Anzeige die Person kam, und suche im Notion-CRM nach früheren Gesprächen.","body_vi":"Xem khách đến từ quảng cáo nào và tìm lịch sử trò chuyện trong CRM Notion."},
     {"de":"Persönlich begrüßen","vi":"Chào hỏi thân thiện","body_de":"Sprich die Person mit Namen an und stell dich vor. Kunden schreiben wir auf Vietnamesisch.","body_vi":"Gọi tên khách và giới thiệu bản thân. Với khách hàng, chúng ta nhắn bằng tiếng Việt."},
     {"de":"Bedarf mit nur zwei Fragen klären","vi":"Tìm hiểu nhu cầu: chỉ hỏi 2 điều","body_de":"Beantworte zuerst die Frage der Person. Dann frag nur: Wo wohnst du? Welches Niveau hast du? Keine weiteren und keine offenen Fragen – jede Frage ist eine Hausaufgabe für den Kunden.","body_vi":"Trả lời câu hỏi của khách trước. Sau đó chỉ hỏi: Bạn sống ở đâu? Bạn đang ở trình độ nào? Không hỏi thêm và không hỏi câu mở – mỗi câu hỏi là một bài tập về nhà cho khách."},
     {"de":"Passende Kurse vorstellen und Preis offen nennen","vi":"Giới thiệu lớp phù hợp và nói rõ học phí","body_de":"Schick nur die Kurse, die zu Wohnort und Niveau passen, und nenne den Preis aus der aktuellen Preisliste.","body_vi":"Chỉ gửi những lớp phù hợp với nơi ở và trình độ của khách, và báo học phí theo bảng giá hiện hành."},
     {"de":"Nächsten Schritt vereinbaren und eintragen","vi":"Hẹn bước tiếp theo và ghi lại","body_de":"Probestunde oder Beratung anbieten, zu Zalo wechseln und den Kontakt im CRM anlegen.","body_vi":"Mời học thử hoặc tư vấn, chuyển sang Zalo và tạo liên hệ trong CRM."}]},
   {"type":"template","label_de":"Vorlage · Vietnamesisch","label_vi":"Mẫu tin nhắn","text":"Chào bạn [Tên] ạ! Mình là [Tên nhân viên] từ NaNu NaNa. Cảm ơn bạn đã nhắn tin cho tụi mình. Bạn đang sống ở đâu và đã học tiếng Đức đến trình độ nào rồi ạ?","translation_de":"„Hallo [Name]! Ich bin [Name] von NaNu NaNa. Danke für deine Nachricht. Wo wohnst du, und bis zu welchem Niveau hast du schon Deutsch gelernt?“"},
   {"type":"callout","tone":"tip","de":"Keine Antwort innerhalb von 24 Stunden? Schreib noch einmal nach.","vi":"Khách chưa trả lời trong 24 giờ? Nhắn lại lần nữa."},
   {"type":"callout","tone":"warning","de":"Versprich nie Rabatte oder Leistungen, die nicht in der Preisliste stehen.","vi":"Không bao giờ hứa giảm giá hay quyền lợi không có trong bảng giá."},
   {"type":"heading","de":"Häufige Fehler","vi":"Lỗi thường gặp"},
   {"type":"list","items":[{"de":"Langsam oder zu allgemein antworten.","vi":"Trả lời chậm hoặc quá chung chung."},{"de":"Zu viele oder offene Fragen stellen.","vi":"Hỏi quá nhiều hoặc hỏi câu mở."},{"de":"Fragen stellen, bevor die Frage des Kunden beantwortet ist.","vi":"Hỏi khách trước khi trả lời câu hỏi của khách."},{"de":"Das Gespräch ohne nächsten Schritt beenden.","vi":"Kết thúc trò chuyện mà không có bước tiếp theo."},{"de":"Den Kontakt nicht im CRM eintragen.","vi":"Quên ghi liên hệ vào CRM."}]}]'),
('00000000-0000-0000-0000-0000000b0002', '00000000-0000-0000-0000-00000000a001', 'probestunde-buchen',
 'Probestunde buchen', 'Đặt lịch học thử', 'process', 'handbook', current_date + 40,
 '[{"type":"paragraph","de":"[SCHRITTE EINFÜGEN]","vi":"[THÊM CÁC BƯỚC]"}]'),
('00000000-0000-0000-0000-0000000b0003', '00000000-0000-0000-0000-00000000a001', 'keine-rabatte',
 'Warum wir keine Rabatte am Telefon geben', 'Vì sao không giảm giá qua điện thoại', 'decision', 'handbook', current_date + 150,
 '[{"type":"paragraph","de":"Gleicher, transparenter Preis für alle – Rabatte am Telefon würden dieses Versprechen brechen.","vi":"Giá minh bạch, như nhau cho mọi người – giảm giá qua điện thoại sẽ phá vỡ lời hứa này."}]'),
('00000000-0000-0000-0000-0000000b0004', '00000000-0000-0000-0000-00000000a001', 'kampagne-probestunde',
 'Kampagne „Kostenlose Probestunde“', 'Chiến dịch „Học thử miễn phí“', 'living', 'handbook', null,
 '[{"type":"paragraph","de":"Laufende Facebook-Anzeige. Wer über die Anzeige im Messenger schreibt, bekommt zuerst das Antwort-Skript unten.","vi":"Quảng cáo Facebook đang chạy. Ai nhắn qua quảng cáo trên Messenger sẽ nhận kịch bản trả lời bên dưới."}]'),
('00000000-0000-0000-0000-0000000b0005', '00000000-0000-0000-0000-00000000a001', 'interview',
 'Die Rolle in Kürze', 'Tóm tắt vai trò', 'reference', 'interview', null,
 '[{"type":"paragraph","de":"Du beantwortest Anfragen von jungen Menschen, die in Deutschland studieren oder eine Ausbildung machen möchten – schnell, freundlich und ehrlich.","vi":"Bạn trả lời câu hỏi của các bạn trẻ muốn du học hoặc học nghề tại Đức – nhanh, thân thiện và trung thực."},
   {"type":"video","url":"","caption_de":"Ein Tag im Sales-Team (YouTube-Link einfügen)","caption_vi":"Một ngày của đội Sales (thêm link YouTube)"},
   {"type":"heading","de":"Aufgaben","vi":"Nhiệm vụ"},
   {"type":"list","items":[{"de":"Anfragen über Messenger, Zalo und Telefon beantworten","vi":"Trả lời yêu cầu qua Messenger, Zalo và điện thoại"},{"de":"Zu Kurs, Niveau und Weg nach Deutschland beraten","vi":"Tư vấn khóa học, trình độ và con đường sang Đức"},{"de":"Probestunden, Anmeldung und Übergabe an Student Support","vi":"Học thử, đăng ký và bàn giao cho Hỗ trợ học viên"}]},
   {"type":"heading","de":"So sieht „großartig“ aus","vi":"Thế nào là „xuất sắc“"},
   {"type":"list","items":[{"de":"Antwortet ehrlich – auch wenn die Antwort „Nein“ ist","vi":"Trả lời trung thực – kể cả khi câu trả lời là „không“"},{"de":"Nennt Preise offen und erklärt, was enthalten ist","vi":"Nói rõ học phí và những gì đã bao gồm"},{"de":"Jedes Gespräch endet mit einem klaren nächsten Schritt","vi":"Mỗi cuộc trò chuyện kết thúc bằng bước tiếp theo rõ ràng"}]},
   {"type":"heading","de":"Anforderungen","vi":"Yêu cầu"},
   {"type":"list","items":[{"de":"Vietnamesisch (Muttersprache)","vi":"Tiếng Việt bản ngữ"},{"de":"Deutsch: [NIVEAU]","vi":"Tiếng Đức: [TRÌNH ĐỘ]"},{"de":"Klare schriftliche Kommunikation, Empathie","vi":"Viết rõ ràng, đồng cảm"}]},
   {"type":"heading","de":"Interviewfragen","vi":"Câu hỏi phỏng vấn"},
   {"type":"list","ordered":true,"items":[{"de":"Erzähl von einem Gespräch, in dem jemand unsicher war. Was hast du getan?","vi":"Kể về một lần khách hàng còn phân vân. Bạn đã làm gì?"},{"de":"„Bei einer anderen Schule ist es günstiger.“ Wie antwortest du?","vi":"„Trung tâm khác rẻ hơn.“ Bạn trả lời thế nào?"},{"de":"Wie organisierst du 40 offene Chats an einem Montagmorgen?","vi":"Bạn sắp xếp 40 tin nhắn chưa trả lời vào sáng thứ Hai thế nào?"}]},
   {"type":"heading","de":"Testaufgabe: Messenger-Simulation","vi":"Bài test: Mô phỏng Messenger"},
   {"type":"callout","tone":"tip","de":"Beantworte drei Nachrichten einer erfundenen Interessentin direkt hier. Wir achten auf Ton, Richtigkeit und den nächsten Schritt. Du hast einen Versuch.","vi":"Trả lời ba tin nhắn của một khách hàng giả định ngay tại đây. Chúng tôi đánh giá giọng điệu, độ chính xác và bước tiếp theo. Bạn có một lượt làm."},
   {"type":"chat","id":"sales-test","customer":"Linh",
    "intro_de":"Linh schreibt der NaNu-NaNa-Seite auf Messenger. Antworte so, wie du es im Job tun würdest – auf Vietnamesisch. Die Zeit läuft ab jeder neuen Nachricht.",
    "intro_vi":"Linh nhắn tin cho trang NaNu NaNa trên Messenger. Hãy trả lời như khi bạn đang làm việc – bằng tiếng Việt. Thời gian được tính từ mỗi tin nhắn mới.",
    "messages":[
      {"text":"Chào ad\n\nCho mình hỏi học phí khoá A1 bao nhiêu vậy ạ?","translation_de":"„Hallo Admin! Darf ich fragen, wie viel der A1-Kurs kostet?“"},
      {"text":"Mình đang học lớp 12, muốn sang Đức học nghề điều dưỡng. Giờ mới bắt đầu học tiếng Đức thì có kịp không ạ?","translation_de":"„Ich bin in der 12. Klasse und möchte in Deutschland eine Pflege-Ausbildung machen. Schaffe ich das, wenn ich jetzt erst mit Deutsch anfange?“"},
      {"text":"Trung tâm kia rẻ hơn bên mình 2 triệu lận\n\nBên mình có giảm giá gì không ad?","translation_de":"„Bei der anderen Schule ist es ganze 2 Millionen günstiger. Gibt es bei euch irgendeinen Rabatt?“"}]}]');

-- ---------------------------------------------------------------- Verkaufstrichter (Sales + Customer Success)
insert into public.pages (id, area_id, slug, title_de, title_vi, kind, section, verified_until, body) values
('00000000-0000-0000-0000-0000000b0006', '00000000-0000-0000-0000-00000000a001', 'verkaufstrichter',
 'Verkaufstrichter: vom Erstkontakt bis zur Zahlung', 'Phễu bán hàng: từ liên hệ đầu tiên đến khi đóng tiền', 'process', 'handbook', current_date + 90,
 '[{"type": "paragraph", "de": "Jedes Unternehmen hat einen Verkaufstrichter. Bei uns hat er sieben Stufen, von Marketing über Beratung bis zum Unterricht. Auf jeder Stufe springen Interessenten ab. Diese Seite zeigt, was Sales auf den Stufen 2 bis 5 tut, warum wir dort Kunden verlieren und was dagegen hilft.", "vi": "Doanh nghiệp nào cũng có một phễu bán hàng. Phễu của mình có bảy bước, từ marketing, tư vấn đến giảng dạy. Ở mỗi bước đều có khách rời đi. Trang này cho biết đội Sales làm gì ở bước 2 đến 5, vì sao mình mất khách ở đó và cách cải thiện."},
   {"type": "heading", "de": "Die sieben Stufen", "vi": "Bảy bước của phễu"},
   {"type": "list", "items": [{"de": "Bekanntheit – Marketing", "vi": "Biết đến – Marketing"},
   {"de": "Erstkontakt – Sales", "vi": "Liên hệ đầu tiên – Sales"},
   {"de": "Bedarf klären – Sales", "vi": "Tìm hiểu nhu cầu – Sales"},
   {"de": "Passende Kurse vorstellen – Sales", "vi": "Giới thiệu lớp phù hợp – Sales"},
   {"de": "Angebot & Abschluss – Sales", "vi": "Báo giá & chốt – Sales"},
   {"de": "Sofort mit dem Lernen beginnen (Onboarding) – Customer Success", "vi": "Bắt đầu học ngay (Onboarding) – Chăm sóc học viên"},
   {"de": "Kundenbindung – Customer Success mit den Lehrkräften", "vi": "Giữ chân học viên – Chăm sóc học viên cùng giáo viên"}], "ordered": true},
   {"type": "heading", "de": "1 · Bekanntheit", "vi": "1 · Biết đến"},
   {"type": "paragraph", "de": "Unsere Social-Media-Kanäle erreichen jeden Tag Tausende Menschen. Bien und Phương verbessern laufend Videos und Anzeigen, damit wir noch mehr Menschen erreichen.", "vi": "Các kênh mạng xã hội của mình tiếp cận hàng nghìn người mỗi ngày. Bien và Phương liên tục cải thiện video và quảng cáo để tiếp cận nhiều người hơn."},
   {"type": "conversation", "customer": "Minh Anh", "note_de": "Gute Inhalte bringen Nachrichten wie diese: Die Person bezieht sich auf ein konkretes Video und hat schon Vertrauen.", "note_vi": "Nội dung tốt mang lại những tin nhắn như thế này: khách nhắc đến một video cụ thể và đã có sẵn sự tin tưởng.", "messages": [{"from": "customer", "text": "Chào ad, mình xem video bên mình về du học nghề Đức, thấy dễ hiểu quá 😍", "translation_de": "„Hallo Admin, ich habe euer Video zur Ausbildung in Deutschland gesehen – total verständlich 😍“", "stamp_de": "Kam über ein Facebook-Video · 20:14", "stamp_vi": "Đến từ một video Facebook · 20:14"},
   {"from": "customer", "text": "Bên mình có lớp tiếng Đức online không ạ?", "translation_de": "„Habt ihr Online-Deutschkurse?“"}]},
   {"type": "callout", "tone": "warning", "de": "Mögliche Ursache für Verluste: Wir posten nicht oft genug, oder die Inhalte sind noch nicht gut genug.", "vi": "Lý do có thể mất khách: đăng bài chưa đủ thường xuyên, hoặc chất lượng nội dung chưa tốt."},
   {"type": "heading", "de": "2 · Erstkontakt: sofort antworten", "vi": "2 · Liên hệ đầu tiên: trả lời ngay lập tức"},
   {"type": "paragraph", "de": "Es ist ein großer Schritt für Kunden, uns überhaupt zu schreiben. Deshalb ist das Wichtigste: sofort antworten, bevor sie das Interesse verlieren oder eine andere Schule fragen.", "vi": "Rất khó để khách liên hệ với mình. Vì vậy, điều quan trọng nhất là trả lời ngay, trước khi khách mất hứng thú hoặc hỏi trường khác."},
   {"type": "conversation", "customer": "Minh Anh", "note_de": "Antwort nach einer Minute, persönlich und konkret: Die Frage ist beantwortet, bevor Minh Anh eine andere Schule fragt.", "note_vi": "Trả lời sau một phút, thân thiện và cụ thể: câu hỏi được trả lời trước khi Minh Anh hỏi trường khác.", "messages": [{"from": "customer", "text": "Bên mình có lớp tiếng Đức online không ạ?", "translation_de": "„Habt ihr Online-Deutschkurse?“", "stamp_de": "20:14", "stamp_vi": "20:14"},
   {"from": "me", "text": "Chào Minh Anh ạ! Mình là Trang từ NaNu NaNa 😊 Có nha bạn, bên mình có lớp online và lớp tại Hà Nội, TP.HCM.", "translation_de": "„Hallo Minh Anh! Ich bin Trang von NaNu NaNa 😊 Ja, wir haben Online-Kurse und Kurse in Hà Nội und HCM.“", "stamp_de": "20:15", "stamp_vi": "20:15"}]},
   {"type": "callout", "tone": "warning", "de": "Mögliche Ursache für Verluste: Wir antworten zu langsam, oder die erste Antwort ist zu allgemein.", "vi": "Lý do có thể mất khách: trả lời chậm, hoặc câu trả lời đầu tiên quá chung chung."},
   {"type": "callout", "tone": "tip", "de": "Keine Antwort innerhalb von 24 Stunden? Schreib noch einmal nach.", "vi": "Khách chưa trả lời trong 24 giờ? Nhắn lại lần nữa."},
   {"type": "heading", "de": "3 · Bedarf klären: nur zwei Fragen", "vi": "3 · Tìm hiểu nhu cầu: chỉ hỏi 2 điều"},
   {"type": "list", "items": [{"de": "Wo wohnst du?", "vi": "Bạn sống ở đâu?"},
   {"de": "Welches Niveau hast du?", "vi": "Bạn đang ở trình độ nào?"}], "ordered": true},
   {"type": "paragraph", "de": "Stell nicht zu viele Fragen und keine offenen Fragen. Jede Frage ist eine Hausaufgabe für den Kunden – und vielleicht antwortet er nie.", "vi": "Tránh hỏi quá nhiều hoặc hỏi câu mở. Mỗi câu hỏi là một bài tập về nhà cho khách – và có thể họ sẽ không bao giờ trả lời."},
   {"type": "conversation", "customer": "Minh Anh", "note_de": "Nur Wohnort und Niveau. Als Minh Anh nicht antwortet, fasst Trang am nächsten Tag einmal freundlich nach.", "note_vi": "Chỉ hỏi nơi ở và trình độ. Khi Minh Anh chưa trả lời, hôm sau Trang nhắn lại một lần thật nhẹ nhàng.", "messages": [{"from": "me", "text": "Để mình gửi lớp phù hợp, bạn cho mình hỏi 2 điều nha:\n1. Bạn đang sống ở đâu?\n2. Bạn học tiếng Đức đến trình độ nào rồi?", "translation_de": "„Damit ich dir passende Kurse schicken kann, zwei kurze Fragen: 1. Wo wohnst du? 2. Bis zu welchem Niveau hast du schon Deutsch gelernt?“", "stamp_de": "20:15", "stamp_vi": "20:15"},
   {"from": "me", "text": "Minh Anh ơi, bạn cho mình biết nơi ở và trình độ để mình gửi lịch lớp phù hợp nha 😊", "translation_de": "„Minh Anh, sag mir kurz Wohnort und Niveau, dann schicke ich dir die passenden Kurse 😊“", "stamp_de": "Am nächsten Tag · 19:30", "stamp_vi": "Hôm sau · 19:30"},
   {"from": "customer", "text": "Dạ mình ở Hà Nội, mới học xong A1 ạ", "translation_de": "„Ich wohne in Hà Nội und habe gerade A1 abgeschlossen.“", "stamp_de": "19:42", "stamp_vi": "19:42"}]},
   {"type": "callout", "tone": "warning", "de": "Mögliche Ursache für Verluste: zu viele oder offene Fragen, oder wir fragen, bevor wir die Frage des Kunden beantwortet haben.", "vi": "Lý do có thể mất khách: hỏi quá nhiều, hỏi câu mở, hoặc hỏi trước khi trả lời câu hỏi của khách."},
   {"type": "heading", "de": "4 · Passende Kurse vorstellen", "vi": "4 · Giới thiệu lớp phù hợp"},
   {"type": "paragraph", "de": "Mit dem, was wir beim Bedarf-Klären erfahren haben, schicken wir nur die Kurse, die zu Wohnort und Niveau passen.", "vi": "Dựa trên thông tin từ bước tìm hiểu nhu cầu, mình chỉ gửi những lớp phù hợp với nơi ở và trình độ của khách."},
   {"type": "conversation", "customer": "Minh Anh", "note_de": "Nur Kurse, die zu Wohnort und Niveau passen – zwei Optionen, die beide ein „Ja“ sein können.", "note_vi": "Chỉ gửi lớp phù hợp với nơi ở và trình độ – hai lựa chọn, cả hai đều có thể là „có“.", "messages": [{"from": "me", "text": "Cảm ơn bạn! Học xong A1 thì bạn học tiếp A2 nha. Ở Hà Nội đang có 2 lớp A2 phù hợp:\n• Lớp tối 2-4-6, 18:30–20:30, khai giảng 10/11\n• Lớp cuối tuần T7–CN, 9:00–11:30, khai giảng 15/11", "translation_de": "„Danke! Nach A1 geht es mit A2 weiter. In Hà Nội gibt es zwei passende A2-Kurse: Abendkurs Mo-Mi-Fr, 18:30–20:30, Start 10.11. · Wochenendkurs Sa–So, 9:00–11:30, Start 15.11.“", "stamp_de": "19:43", "stamp_vi": "19:43"},
   {"from": "customer", "text": "Lớp tối 2-4-6 hợp với mình á. Học phí bao nhiêu vậy ad?", "translation_de": "„Der Abendkurs Mo-Mi-Fr passt mir. Wie viel kostet er?“"}]},
   {"type": "callout", "tone": "info", "de": "Kein passender Kurs? Dann wissen wir trotzdem: Die Person hat Interesse – es gibt nur noch keinen Kurs für sie. Das ist kein verlorener Kunde, sondern ein Zeichen, dass wir mehr Lehrkräfte und Kurse brauchen.", "vi": "Không có lớp phù hợp? Mình vẫn biết khách có nhu cầu – chỉ là chưa có lớp. Đây không phải khách mất đi, mà là dấu hiệu mình cần thêm giáo viên và thêm lớp."},
   {"type": "heading", "de": "5 · Angebot & Abschluss – der wichtigste Schritt", "vi": "5 · Báo giá & chốt – bước quan trọng nhất"},
   {"type": "paragraph", "de": "Schick den Preis und die Leistungen, die der Kunde bekommt. Fünf Regeln:", "vi": "Gửi giá và những quyền lợi khách nhận được. Năm nguyên tắc:"},
   {"type": "steps", "items": [{"de": "Ein Niveau, zur gewünschten Uhrzeit", "vi": "Một trình độ, đúng giờ khách hỏi", "body_de": "Jede zusätzliche Option ist ein Grund, „noch mal darüber nachzudenken“. Wenn du eine Wahl gibst, dann zwei Optionen, die beide ein „Ja“ sind: Abendkurs oder Wochenendkurs.", "body_vi": "Mỗi lựa chọn thêm là một lý do để „suy nghĩ thêm“. Nếu cho chọn: 2 lựa chọn đều là „có“ – lớp tối hoặc cuối tuần."},
   {"de": "Erst die Leistungen, dann der Preis", "vi": "Quyền lợi trước, giá sau", "body_de": "Ein Satz, der an das Ziel des Kunden anknüpft, z. B. „mit derselben Lehrkraft von A1 bis B1, inklusive kostenloser Lern-App“.", "body_vi": "Thêm 1 câu nối với mục tiêu của khách, ví dụ „cùng giáo viên từ A1 lên B1, có app học miễn phí đi kèm“."},
   {"de": "Direkt in der Angebotsnachricht zum Abschluss fragen", "vi": "Hỏi chốt ngay trong tin nhắn báo giá", "body_de": "Nicht auf die Antwort warten, sondern konkret fragen, ob wir den Platz reservieren sollen (Vorlage unten).", "body_vi": "Không chờ khách tự quyết, hỏi cụ thể có giữ chỗ cho khách không (mẫu bên dưới)."},
   {"de": "„Ja“ ist nur ein Schritt", "vi": "Cho „có“ chỉ một bước", "body_de": "Sag klar, was passiert, wenn der Kunde zusagt: wie der Platz reserviert wird und wie er bezahlt – damit er nicht nachfragen muss. Alles passiert im Chat.", "body_vi": "Nói rõ chuyện gì xảy ra khi khách đồng ý: giữ chỗ thế nào, thanh toán ra sao – để khách không phải hỏi. Mọi thứ ở trong chat."},
   {"de": "Das Angebot nicht kalt werden lassen", "vi": "Đừng để báo giá nguội", "body_de": "Bis zum nächsten Tag keine Antwort? Schreib noch einmal mit etwas Neuem (aktuelle freie Plätze oder eine passende Leistung) und frag erneut nach dem Abschluss.", "body_vi": "Đến hôm sau chưa trả lời? Nhắn lại với điều gì mới (cập nhật chỗ trống hoặc một quyền lợi phù hợp) và hỏi chốt lại."}]},
   {"type": "template", "label_de": "Vorlage · Abschlussfrage", "label_vi": "Mẫu · Hỏi chốt", "text": "Chị giữ chỗ cho em lớp tối 2-4-6 khai giảng [ngày] nha?", "translation_de": "„Soll ich dir einen Platz im Abendkurs Mo-Mi-Fr ab [Datum] reservieren?“"},
   {"type": "conversation", "customer": "Minh Anh", "note_de": "Leistungen vor dem Preis, die Abschlussfrage direkt im Angebot, „Ja“ in einem Schritt – und am nächsten Tag ein Nachfassen mit etwas Neuem (freie Plätze).", "note_vi": "Quyền lợi trước giá, hỏi chốt ngay trong tin báo giá, cho „có“ chỉ một bước – và hôm sau nhắn lại với điều mới (số chỗ còn trống).", "messages": [{"from": "me", "text": "Lớp A2 tối 2-4-6 học cùng một giáo viên từ A2 lên B1, có app NaNu Go học miễn phí đi kèm. Học phí: [HỌC PHÍ] cho 42 buổi.", "translation_de": "„Im A2-Abendkurs Mo-Mi-Fr lernst du mit derselben Lehrkraft von A2 bis B1, inklusive kostenloser App NaNu Go. Preis: [PREIS] für 42 Einheiten.“", "stamp_de": "19:44", "stamp_vi": "19:44"},
   {"from": "me", "text": "Mình giữ chỗ cho bạn lớp tối 2-4-6 khai giảng 10/11 nha? Bạn chỉ cần chuyển khoản theo thông tin dưới đây, mình giữ chỗ ngay và gửi xác nhận trong chat này:\n[THÔNG TIN CHUYỂN KHOẢN]", "translation_de": "„Soll ich dir einen Platz im Abendkurs Mo-Mi-Fr ab 10.11. reservieren? Du überweist einfach an die Daten unten, ich reserviere sofort und bestätige hier im Chat.“"},
   {"from": "me", "text": "Minh Anh ơi, lớp tối 2-4-6 chỉ còn 3 chỗ thôi nè. Mình giữ 1 chỗ cho bạn nha?", "translation_de": "„Minh Anh, im Abendkurs Mo-Mi-Fr sind nur noch 3 Plätze frei. Soll ich dir einen reservieren?“", "stamp_de": "Am nächsten Tag · 18:00", "stamp_vi": "Hôm sau · 18:00"},
   {"from": "customer", "text": "Dạ ok ad, mình chuyển khoản liền nha", "translation_de": "„Okay, ich überweise gleich.“", "stamp_de": "18:20", "stamp_vi": "18:20"},
   {"from": "me", "text": "Cảm ơn Minh Anh! Mình đã giữ chỗ cho bạn rồi. Chút nữa bạn sẽ nhận email để bắt đầu học nha 🎉", "translation_de": "„Danke, Minh Anh! Dein Platz ist reserviert. Gleich bekommst du eine E-Mail, damit du sofort loslegen kannst 🎉“"}]},
   {"type": "callout", "tone": "warning", "de": "Mögliche Ursache für Verluste: Meistens ist dem Kunden der Preis zu hoch. Zeig den Wert klarer.", "vi": "Lý do có thể mất khách: phần lớn là do khách thấy giá quá cao. Hãy trình bày giá trị rõ ràng hơn."},
   {"type": "callout", "tone": "info", "de": "Sonderangebote nur, wenn sie offiziell gelten – keine eigenen Rabatte im Chat oder am Telefon.", "vi": "Chỉ đưa ưu đãi đặc biệt khi đó là ưu đãi chính thức – không tự giảm giá qua chat hay điện thoại."},
   {"type": "heading", "de": "Danach: Übergabe an Customer Success", "vi": "Sau đó: bàn giao cho Chăm sóc học viên"},
   {"type": "paragraph", "de": "Nach Anmeldung und Zahlung übernimmt Customer Success die Stufen 6 und 7: Onboarding und Kundenbindung.", "vi": "Sau khi khách đăng ký và thanh toán, đội Chăm sóc học viên phụ trách bước 6 và 7: bắt đầu học và giữ chân học viên."}]'),
('00000000-0000-0000-0000-0000000e0001', '00000000-0000-0000-0000-00000000a002', 'onboarding-und-kundenbindung',
 'Onboarding & Kundenbindung', 'Bắt đầu học & giữ chân học viên', 'process', 'handbook', current_date + 90,
 '[{"type": "paragraph", "de": "Unser Verkaufstrichter hat sieben Stufen. Nach Anmeldung und Zahlung übernimmt Customer Success die letzten beiden: Lernende sollen sofort starten, den Wert sehen und den nächsten Kurs buchen.", "vi": "Phễu bán hàng của mình có bảy bước. Sau khi khách đăng ký và thanh toán, đội Chăm sóc học viên phụ trách hai bước cuối: học viên bắt đầu ngay, thấy giá trị và đăng ký khoá tiếp theo."},
   {"type": "heading", "de": "Die sieben Stufen", "vi": "Bảy bước của phễu"},
   {"type": "list", "items": [{"de": "Bekanntheit – Marketing", "vi": "Biết đến – Marketing"},
   {"de": "Erstkontakt – Sales", "vi": "Liên hệ đầu tiên – Sales"},
   {"de": "Bedarf klären – Sales", "vi": "Tìm hiểu nhu cầu – Sales"},
   {"de": "Passende Kurse vorstellen – Sales", "vi": "Giới thiệu lớp phù hợp – Sales"},
   {"de": "Angebot & Abschluss – Sales", "vi": "Báo giá & chốt – Sales"},
   {"de": "Sofort mit dem Lernen beginnen (Onboarding) – Customer Success", "vi": "Bắt đầu học ngay (Onboarding) – Chăm sóc học viên"},
   {"de": "Kundenbindung – Customer Success mit den Lehrkräften", "vi": "Giữ chân học viên – Chăm sóc học viên cùng giáo viên"}], "ordered": true},
   {"type": "heading", "de": "6 · Sofort mit dem Lernen beginnen", "vi": "6 · Bắt đầu học ngay"},
   {"type": "callout", "tone": "info", "de": "Ziel: Der Kunde sieht sofort den Wert und verlangt nach den Probestunden kein Geld zurück.", "vi": "Mục tiêu: khách thấy giá trị ngay và không yêu cầu hoàn tiền sau buổi học thử."},
   {"type": "paragraph", "de": "Schick sofort alles, was zum Start gebraucht wird – damit der Kunde gleich mit dem Lernen beginnt:", "vi": "Gửi mọi thứ để bắt đầu – ngay lập tức – để khách học được ngay:"},
   {"type": "steps", "items": [{"de": "Onboarding-E-Mail senden", "vi": "Gửi email onboarding"},
   {"de": "Die App NaNu Go schicken", "vi": "Gửi app NaNu Go"}]},
   {"type": "callout", "tone": "warning", "de": "Mögliche Ursache für Verluste: Der Kunde sieht noch keinen Wert, oder der Start ist verwirrend. Unterstütze in der Onboarding-Phase besser.", "vi": "Lý do có thể mất khách: khách chưa thấy giá trị, hoặc lúc bắt đầu còn rối. Hãy hỗ trợ tốt hơn trong giai đoạn onboarding."},
   {"type": "heading", "de": "7 · Kundenbindung", "vi": "7 · Giữ chân học viên"},
   {"type": "callout", "tone": "info", "de": "Ziel: Die Lernenden buchen den nächsten Kurs.", "vi": "Mục tiêu: học viên đăng ký khoá tiếp theo."},
   {"type": "paragraph", "de": "Behalte laufend im Blick:", "vi": "Theo dõi liên tục:"},
   {"type": "list", "items": [{"de": "Anwesenheit", "vi": "Điểm danh"},
   {"de": "Feedback der Lehrkraft", "vi": "Phản hồi giáo viên"},
   {"de": "Übungen in der App", "vi": "Bài tập trên app"}]},
   {"type": "callout", "tone": "tip", "de": "Jemand fehlt, kommt nicht gut mit oder macht die Übungen in der App nicht? Melde dich sofort und biete Hilfe an.", "vi": "Học viên vắng, học chưa tốt hoặc không làm bài trên app? Liên hệ ngay và hỗ trợ."},
   {"type": "callout", "tone": "warning", "de": "Mögliche Ursache für Verluste: Die Lernenden sind mit unserem Service nicht zufrieden.", "vi": "Lý do có thể mất khách: học viên chưa hài lòng với dịch vụ."},
   {"type": "heading", "de": "So unterstützen wir besser", "vi": "Cách hỗ trợ tốt hơn"},
   {"type": "list", "items": [{"de": "Die App NaNu Go vorstellen", "vi": "Giới thiệu app NaNu Go"},
   {"de": "Regelmäßig nachfragen, auf Basis des Feedbacks der Lehrkraft", "vi": "Hỏi thăm thường xuyên dựa trên phản hồi của giáo viên"},
   {"de": "Empfehlungen geben und zusätzlich unterstützen", "vi": "Đưa lời khuyên và hỗ trợ thêm"}]}]');

